def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a in me if a == 'D')

    # Endgame: strong coop -> grab DC; else mirror/defect
    if n >= 95:
        if opp_c * 10 >= n * 6:
            return 'D'
        if opp_c * 10 <= n * 4:
            return 'D'
        return opp[-1]

    # Persistent defector -> defect
    if n >= 6 and opp_d * 10 >= n * 9:
        return 'D'

    # No opponent defections ever: pure cooperator. Exploit heavily late,
    # but keep some CC to stay safe.
    if opp_d == 0:
        if n < 6:
            return 'C'
        if n >= 80:
            return 'D'
        if n >= 30:
            return 'D' if rng.random() < 0.5 else 'C'
        if n >= 12:
            return 'D' if rng.random() < 0.2 else 'C'
        return 'C'

    last_opp = opp[-1]
    last_me = me[-1]

    # Generous tit-for-tat core with limited memory.
    if last_opp == 'C':
        # Opponent cooperated; occasionally probe if they never punish us.
        if my_d >= 3 and opp_d == 0:
            return 'D'
        # If opponent has been quite cooperative but we got away with defection
        # before, don't push too hard.
        if my_d > 0 and opp_d <= n // 10:
            return 'C'
        return 'C'

    # Opponent defected.
    # Ratio-based forgiveness.
    coop_rate = opp_c / n
    # Count consecutive opponent defections at tail
    streak = 0
    for a in reversed(opp):
        if a == 'D':
            streak += 1
        else:
            break

    if streak >= 3:
        return 'D' if rng.random() < 0.9 else 'C'

    if streak == 2:
        if coop_rate > 0.65:
            return 'C' if rng.random() < 0.4 else 'D'
        return 'D'

    # Single defection.
    if coop_rate > 0.7:
        # Forgive often, but not if we just cooperated and they keep exploiting.
        if rng.random() < 0.55:
            return 'C'
        return 'D'
    if coop_rate > 0.4:
        return 'D' if rng.random() < 0.75 else 'C'
    return 'D' if rng.random() < 0.92 else 'C'
